import subprocess
from flask import Flask, jsonify

app = Flask(__name__)

BACKUP_MEMORIES_SCRIPT = "/home/squinlan/cliff_ai/sysadmin/backup/memories.sh"
VIKUNJA_SCRIPT = "/home/squinlan/cliff_ai/sysadmin/backup/vikunja.sh"


def run_script(path: str) -> dict:
    """Run a script and return a small status dict."""
    try:
        result = subprocess.run(
            [path],
            capture_output=True,
            text=True,
            check=False,
        )
        return {
            "script": path,
            "returncode": result.returncode,
            "stdout": result.stdout.strip(),
            "stderr": result.stderr.strip(),
            "ok": result.returncode == 0,
        }
    except Exception as e:
        return {
            "script": path,
            "returncode": -1,
            "stdout": "",
            "stderr": str(e),
            "ok": False,
        }


@app.route("/backup/memories", methods=["POST"])
def backup_memories():
    # Run filesystem snapshot
    mem_status = run_script(BACKUP_MEMORIES_SCRIPT)

    # Run Vikunja DB dump
    vik_status = run_script(VIKUNJA_SCRIPT)

    overall_ok = mem_status["ok"] and vik_status["ok"]

    return jsonify(
        {
            "status": "ok" if overall_ok else "error",
            "memories": mem_status,
            "tasks_db": vik_status,
        }
    ), 200 if overall_ok else 500


if __name__ == "__main__":
    # Internal Cliff service: exposed on 8101
    app.run(host="0.0.0.0", port=8101)
